test('Avenue trade rows create separate idempotent evidence-linked proposals',async()=>{
 const f=await fixture(),custody='custody-fixture-'+randomUUID(),document='avenue-fixture-'+randomUUID();
 await db.query("INSERT INTO app.custody_accounts(household_id,id,owner_id,institution_id,external_reference,identity_basis) VALUES($1,$2,'owner1','avenue-securities','fixture-account','observed_reference')",[f.h,custody]);
 const scope=JSON.stringify(['Fixture',`custody:${custody}`]),account=accountId(scope);
 await db.query("INSERT INTO app.accounts(household_id,id,owner_id,source_scope,identity_status) VALUES($1,$2,'owner1',$3,'known')",[f.h,account,scope]);
 await db.query("INSERT INTO app.source_documents(household_id,id,owner_id,source_system,report_kind,original_name,content_sha256,storage_key,date_basis) VALUES($1,$2,'owner1','Avenue','movement','fixture.pdf',$3,'fixture','trade_date')",[f.h,document,hash(document)]);
 for(const [index,code,price] of [[2,'PETR4',30],[3,'VALE3',40]] as const){const raw={side:'buy',currency:'USD',quantity:2,unit_price:price,fees_minor:0,instrument_code:code,trade_date:'2026-11-03',settlement_date:'2026-11-04',principal_minor:price*200};await db.query("INSERT INTO app.source_assertions(household_id,id,document_id,owner_id,source_sheet,source_row,assertion_kind,custody_account_id,instrument_code,asserted_on,quantity,raw_row,interpretation_status) VALUES($1,$2,$3,'owner1','fixture',$4,'movement',$5,$6,'2026-11-03',2,$7,'observed')",[f.h,'assertion-'+randomUUID(),document,index,custody,code,JSON.stringify(raw)]);}
 assert.deepEqual(await prepareAvenueTradeProposals(db,f.h,document),{created:2,existing:0,blocked:[]});
 assert.deepEqual(await prepareAvenueTradeProposals(db,f.h,document),{created:0,existing:2,blocked:[]});
 assert.equal((await db.query('SELECT count(*)::int AS n FROM app.avenue_trade_proposal_links WHERE household_id=$1',[f.h])).rows[0].n,2);
 assert.equal((await db.query('SELECT facts_revision::text FROM app.household_state WHERE household_id=$1',[f.h])).rows[0].facts_revision,'0');
 const listed=(await listProposals(db,f.h,'pending')).proposals.filter(p=>p.avenue_document_id===document);assert.equal(listed.length,2);assert.equal(listed[0].settlement_date,'2026-11-04');
 const chosen=listed[0];await approve(db,f.h,f.actor,chosen.id,'avenue-approve-01',{version:chosen.version,summary_hash:chosen.summary_hash,expected_facts_revision:'0'});
 const applied=await db.query('SELECT settlement_date::text,evidence_id FROM app.events WHERE household_id=$1 AND id=$2',[f.h,'proposal:'+chosen.id]);assert.equal(applied.rows[0].settlement_date,'2026-11-04');assert.match(applied.rows[0].evidence_id,/^avenue-assertion:/);

 const copy='avenue-copy-'+randomUUID();await db.query("INSERT INTO app.source_documents(household_id,id,owner_id,source_system,report_kind,original_name,content_sha256,storage_key,date_basis) VALUES($1,$2,'owner1','Avenue','movement','copy.pdf',$3,'fixture','trade_date')",[f.h,copy,hash(copy)]);
 await db.query("INSERT INTO app.source_assertions(household_id,id,document_id,owner_id,source_sheet,source_row,assertion_kind,custody_account_id,instrument_code,asserted_on,quantity,raw_row,interpretation_status) SELECT household_id,$3,$4,owner_id,source_sheet,source_row,assertion_kind,custody_account_id,instrument_code,asserted_on,quantity,raw_row,interpretation_status FROM app.source_assertions WHERE household_id=$1 AND document_id=$2 AND instrument_code='PETR4'",[f.h,document,'assertion-'+randomUUID(),copy]);
 const duplicate=await prepareAvenueTradeProposals(db,f.h,copy);assert.equal(duplicate.created,0);assert.equal(duplicate.blocked.length,1);assert.equal((await db.query("SELECT count(*)::int n FROM app.confirmation_items WHERE household_id=$1 AND category='Avenue'",[f.h])).rows[0].n,1);

});
test('proposal commands require a known account owned by the selected investor and are idempotent',async()=>{
 const f=await fixture(),evidenceId=await manualEvidence(f.h),input={request_key:'proposal-request-01',owner_id:'owner1',account_id:'account1',instrument_code:'VALE3',currency:'BRL',side:'buy',quantity:'2.5',unit_price:'61.20',fees_minor:'15',effective_date:'2026-08-10',source_evidence:{kind:'manual_text' as const,id:evidenceId}};
 const created=await createProposal(db,f.h,f.actor,input.request_key,input);assert.equal(created.status,'pending');assert.equal(created.replayed,false);
 const replay=await createProposal(db,f.h,f.actor,input.request_key,input);assert.equal(replay.proposal_id,created.proposal_id);assert.equal(replay.replayed,true);
 const raceInput={...input,request_key:'proposal-race-01',instrument_code:'ITUB4',source_evidence:{kind:'manual_text' as const,id:await manualEvidence(f.h,'owner1','Comprei ITUB4')}};const concurrent=await Promise.all([createProposal(db,f.h,f.actor,raceInput.request_key,raceInput),createProposal(db,f.h,f.actor,raceInput.request_key,raceInput)]);assert.equal(concurrent[0].proposal_id,concurrent[1].proposal_id);assert.deepEqual(concurrent.map(r=>r.replayed).sort(),[false,true]);
 await assert.rejects(()=>createProposal(db,f.h,f.actor,input.request_key,{...input,quantity:'3'}),(e:unknown)=>e instanceof Conflict&&e.code==='IDEMPOTENCY_MISMATCH');
 await assert.rejects(()=>createProposal(db,f.h,'foreign','proposal-request-02',input),(e:unknown)=>e instanceof Conflict&&e.code==='FORBIDDEN');
 await assert.rejects(()=>createProposal(db,f.h,f.actor,'proposal-request-03',{...input,account_id:'other-account'}),(e:unknown)=>e instanceof Conflict&&e.code==='ACCOUNT_OWNER_MISMATCH');
 const pending=await listProposals(db,f.h,'pending');assert.equal(pending.proposals.length,4);
 assert.equal(pending.proposals.find(p=>p.source_evidence_id===evidenceId)?.source_evidence_text,'Compré una acción PETR4 por BRL 30 el 10/08/2026');assert.equal((await db.query('SELECT status FROM app.manual_intakes WHERE household_id=$1 AND id=$2',[f.h,evidenceId])).rows[0].status,'linked');
 await assert.rejects(()=>createProposal(db,f.h,f.actor,'proposal-reuse-01',input),(e:unknown)=>e instanceof Conflict&&e.code==='EVIDENCE_ALREADY_LINKED');
 await db.query("INSERT INTO app.owners VALUES($1,'owner2','Other')",[f.h]);const wrongOwnerEvidence=await manualEvidence(f.h,'owner2');await assert.rejects(()=>createProposal(db,f.h,f.actor,'proposal-wrong-evidence-01',{...input,source_evidence:{kind:'manual_text',id:wrongOwnerEvidence}}),(e:unknown)=>e instanceof Conflict&&e.code==='EVIDENCE_OWNER_MISMATCH');
 const photoId=randomUUID();await db.query("INSERT INTO app.manual_photo_evidence(household_id,upload_id,owner_id,file_name,content_sha256) VALUES($1,$2,'owner1','comprobante.png',$3)",[f.h,photoId,'f'.repeat(64)]);const photoProposal=await createProposal(db,f.h,f.actor,'proposal-photo-01',{...input,source_evidence:{kind:'manual_photo',id:photoId}});assert.equal(photoProposal.status,'pending');assert.equal((await db.query('SELECT status FROM app.manual_photo_evidence WHERE household_id=$1 AND upload_id=$2',[f.h,photoId])).rows[0].status,'linked');assert.equal((await listProposals(db,f.h,'pending')).proposals.find(p=>p.source_evidence_id===photoId)?.source_evidence_text,'comprobante.png');
 const decision={version:created.version,summary_hash:created.summary_hash,expected_facts_revision:'0'};
 const rejected=await rejectProposal(db,f.h,f.actor,created.proposal_id,'reject-request-01',decision);assert.equal(rejected.status,'rejected');assert.equal(rejected.replayed,false);
 const rejectedReplay=await rejectProposal(db,f.h,f.actor,created.proposal_id,'reject-request-01',decision);assert.equal(rejectedReplay.replayed,true);
 await assert.rejects(()=>rejectProposal(db,f.h,f.actor,created.proposal_id,'reject-request-02',{...decision,expected_facts_revision:'1'}),(e:unknown)=>e instanceof Conflict&&e.code==='PROPOSAL_NOT_PENDING');
 const reviewer='draft-reviewer-'+randomUUID();await db.query('INSERT INTO app.actors VALUES($1,$2)',[reviewer,'Draft-only reviewer']);await db.query("INSERT INTO app.memberships VALUES($1,$2,'reviewer')",[f.h,reviewer]);const draft=await createProposal(db,f.h,reviewer,'reviewer-draft-01',{owner_id:'owner1',account_id:'account1',instrument_code:'BBDC4',currency:'BRL',side:'buy',quantity:'1',unit_price:'10',effective_date:'2026-08-11',source_evidence:{kind:'manual_text',id:await manualEvidence(f.h)}});assert.equal(draft.status,'pending');await assert.rejects(()=>rejectProposal(db,f.h,reviewer,draft.proposal_id,'reviewer-reject-01',{version:draft.version,summary_hash:draft.summary_hash,expected_facts_revision:'0'}),(e:unknown)=>e instanceof Conflict&&e.code==='FORBIDDEN');assert.equal((await db.query('SELECT count(*) FROM app.events WHERE household_id=$1',[f.h])).rows[0].count,'0');
 assert.equal((await listProposals(db,f.h,'rejected')).proposals.length,1);assert.equal((await db.query('SELECT facts_revision FROM app.household_state WHERE household_id=$1',[f.h])).rows[0].facts_revision,'0');assert.equal((await db.query('SELECT count(*) FROM app.events WHERE household_id=$1',[f.h])).rows[0].count,'0');
});
test('approving a proposal atomically publishes a rebuilt portfolio that includes the applied event',async()=>{
 const dir=await mkdtemp(join(tmpdir(),'juanca-command-publish-'));
 try{
  const h='command-publish-'+randomUUID(),actor='command-actor-'+randomUUID(),owner='Fixture',accountRef='custody-fixture',position={owner,account:accountRef,currency:'BRL',instrument_code:'PETR4',quantity:'10',unit_price:'30',market_value_cents:'30000',reference_date:'2026-08-01'};
  const tables={imports:[{id:'position-import',user_id:h,owner,status:'processed',file_type:'positions',reference_date:'2026-08-01',created_at:'2026-08-02 00:00:00'}],import_records:[{id:1,import_id:'position-import',record_kind:'position',payload:JSON.stringify(position)}],market_quotes:[],fx_observations:[],portfolio_revisions:[{user_id:h,revision:0}],transaction_proposals:[],review_decisions:[],cost_basis:[],chat_messages:[],proposal_applications:[]};const content={format:1,tables,conversation_archive:[]};const canonical=JSON.stringify(content);const path=join(dir,'envelope.json');await writeFile(path,JSON.stringify({source_sha256:hash(canonical),exported_at:'2026-08-03T00:00:00.000Z',canonical_content:canonical,content}));
  const run=await importEnvelope(db,path),ownerId=(await db.query('SELECT id FROM app.owners WHERE household_id=$1 AND display_name=$2',[h,owner])).rows[0].id,scope=JSON.stringify([owner,'account:'+accountRef]),accountId='account-'+hash(scope).slice(0,24),doc='command-position-doc',assertion='command-position-assertion';await db.query('INSERT INTO app.actors VALUES($1,$2)',[actor,'synthetic reviewer']);await db.query("INSERT INTO app.memberships VALUES($1,$2,'owner')",[h,actor]);await db.query("INSERT INTO app.source_documents(household_id,id,owner_id,source_system,report_kind,original_name,content_sha256,storage_key,effective_as_of,date_basis) VALUES($1,$2,$3,'fixture','position','position.json',$4,$2,'2026-08-01','report_date')",[h,doc,ownerId,'b'.repeat(64)]);await db.query("INSERT INTO app.source_assertions(household_id,id,document_id,owner_id,source_sheet,source_row,assertion_kind,instrument_code,asserted_on,quantity,raw_row,interpretation_status) VALUES($1,$2,$3,$4,'Positions',2,'position','PETR4','2026-08-01',10,'{}','observed')",[h,assertion,doc,ownerId]);await db.query('INSERT INTO app.holdings(household_id,account_id,instrument_code,currency,quantity,coverage_status,opening_as_of,opening_assertion_id) VALUES($1,$2,\'PETR4\',\'BRL\',10,\'verified\',\'2026-08-01\',$3)',[h,accountId,assertion]);
  const before=await publish(db,run.run_id,h,'2026-08-03','2026-08-03T00:00:00.000Z'),proposalEvidence=await manualEvidence(h,ownerId);const proposalInput={owner_id:ownerId,account_id:accountId,instrument_code:'PETR4',currency:'BRL',side:'sell',quantity:'2',unit_price:'31',fees_minor:'25',effective_date:'2026-08-04',source_evidence:{kind:'manual_text' as const,id:proposalEvidence}},proposal=await createProposal(db,h,actor,'publish-request-01',proposalInput);
  const result=await approve(db,h,actor,proposal.proposal_id,'publish-approve-01',{version:proposal.version,summary_hash:proposal.summary_hash,expected_facts_revision:'0'});assert.equal(result.status,'applied');assert.ok(result.portfolio_version);assert.notEqual(result.portfolio_version,before.portfolio_version);
  const after=await portfolio(db,h);assert.equal(after.portfolio_version,result.portfolio_version);assert.equal(after.positions.find((p:{instrument_code:string;quantity:string})=>p.instrument_code==='PETR4')?.quantity,'8');assert.equal((await db.query('SELECT quantity FROM app.holdings WHERE household_id=$1 AND account_id=$2 AND instrument_code=\'PETR4\'',[h,accountId])).rows[0].quantity,'8');assert.equal((await db.query('SELECT facts_revision FROM app.household_state WHERE household_id=$1',[h])).rows[0].facts_revision,'1');assert.equal((await db.query('SELECT count(*) FROM app.audit_log WHERE household_id=$1 AND action=\'proposal_applied\'',[h])).rows[0].count,'1');assert.equal((await db.query("SELECT evidence_id FROM app.events WHERE household_id=$1 AND id=$2",[h,'proposal:'+proposal.proposal_id])).rows[0].evidence_id,`manual_text:${proposalEvidence}`);
  const backdatedEvidence=await manualEvidence(h,ownerId,'También confirmé otra operación el día del snapshot');const backdated=await createProposal(db,h,actor,'publish-backdated-01',{...proposalInput,side:'buy',quantity:'1',effective_date:'2026-08-01',source_evidence:{kind:'manual_text',id:backdatedEvidence}});
  await assert.rejects(()=>approve(db,h,actor,backdated.proposal_id,'publish-backdated-approve',{version:backdated.version,summary_hash:backdated.summary_hash,expected_facts_revision:'1'}),(error:unknown)=>error instanceof Conflict&&error.code==='EVENT_AT_OR_BEFORE_SNAPSHOT');
  assert.equal((await db.query('SELECT count(*) FROM app.events WHERE household_id=$1',[h])).rows[0].count,'1');assert.equal((await db.query('SELECT status FROM app.proposals WHERE household_id=$1 AND id=$2',[h,backdated.proposal_id])).rows[0].status,'pending');
 }finally{await rm(dir,{recursive:true,force:true});}
});
test('a reviewed buy with evidence can open a new invested position without a prior snapshot',async()=>{
 const dir=await mkdtemp(join(tmpdir(),'juanca-opening-event-'));
 try{
  const h='opening-event-'+randomUUID(),actor='opening-actor-'+randomUUID();
  const tables={imports:[{id:'empty-position-import',user_id:h,owner:'Fixture',status:'processed',file_type:'positions',reference_date:'2026-08-01',created_at:'2026-08-02 00:00:00'}],import_records:[],market_quotes:[],fx_observations:[],portfolio_revisions:[{user_id:h,revision:0}],transaction_proposals:[],review_decisions:[],cost_basis:[],chat_messages:[],proposal_applications:[]};
  const content={format:1,tables,conversation_archive:[]},canonical=JSON.stringify(content),path=join(dir,'empty.json');await writeFile(path,JSON.stringify({source_sha256:hash(canonical),exported_at:'2026-08-03T00:00:00.000Z',canonical_content:canonical,content}));
  const run=await importEnvelope(db,path);await db.query('INSERT INTO app.actors VALUES($1,$2)',[actor,'Opening fixture actor']);
  // importEnvelope creates the household and owner from the envelope.
  const owner=ownerId('Fixture');await db.query("INSERT INTO app.owners VALUES($1,$2,'Fixture')",[h,owner]);
  await db.query("INSERT INTO app.memberships VALUES($1,$2,'owner')",[h,actor]);await db.query("INSERT INTO app.accounts(household_id,id,owner_id,source_scope,identity_status) VALUES($1,'new-account',$2,'[\"Fixture\",\"custody:fixture\"]','known')",[h,owner]);
  const before=await publish(db,run.run_id,h,'2026-08-03','2026-08-03T00:00:00.000Z'),evidenceId=await manualEvidence(h,owner,'Compré 2 VALE3 a BRL 60 el 04/08/2026');
  const input={owner_id:owner,account_id:'new-account',instrument_code:'VALE3',currency:'BRL',side:'buy',quantity:'2',unit_price:'60',effective_date:'2026-08-04',source_evidence:{kind:'manual_text' as const,id:evidenceId}};
  const proposal=await createProposal(db,h,actor,'new-opening-proposal',input),result=await approve(db,h,actor,proposal.proposal_id,'new-opening-approve',{version:proposal.version,summary_hash:proposal.summary_hash,expected_facts_revision:'0'});
  assert.equal(result.status,'applied');assert.notEqual(result.portfolio_version,before.portfolio_version);
  const position=(await portfolio(db,h)).positions.find((p:{instrument_code:string})=>p.instrument_code==='VALE3');assert.equal(position?.quantity,'2');
  const holding=(await db.query("SELECT quantity::text,coverage_status,opening_as_of::text,opening_event_id FROM app.holdings WHERE household_id=$1 AND instrument_code='VALE3'",[h])).rows[0];assert.deepEqual(holding,{quantity:'2',coverage_status:'verified',opening_as_of:'2026-08-04',opening_event_id:`proposal:${proposal.proposal_id}`});
  const readiness=await db.query('SELECT num_nonnulls(opening_assertion_id,opening_document_id,opening_event_id)::int AS evidence_count FROM app.holdings WHERE household_id=$1 AND instrument_code=\'VALE3\'',[h]);assert.equal(readiness.rows[0].evidence_count,1);
 }finally{await rm(dir,{recursive:true,force:true});}
});
test('real PostgreSQL serializes concurrent sales without tracking cash, and commits ledger/audit atomically',async()=>{
 const f=await fixture();await assert.rejects(()=>db.query("INSERT INTO app.holdings(household_id,account_id,instrument_code,currency,quantity,coverage_status) VALUES($1,'account1','NO_EVIDENCE','BRL',1,'verified')",[f.h]));const results=await Promise.allSettled(['p1','p2'].map(id=>approve(db,f.h,f.actor,id,'command-'+id,f.body)));assert.equal(results.filter(r=>r.status==='fulfilled').length,1,JSON.stringify(results.map(r=>r.status==='rejected'?String(r.reason):'ok')));const winner=results[0].status==='fulfilled'?'p1':'p2';const loser=winner==='p1'?'p2':'p1';const failed=results.find(r=>r.status==='rejected') as PromiseRejectedResult;assert.equal(failed.reason.code,'STALE_PORTFOLIO');
 const replay=await approve(db,f.h,f.actor,winner,'command-'+winner,f.body);assert.equal(replay.replayed,true);await assert.rejects(()=>approve(db,f.h,f.actor,winner,'command-'+winner,{...f.body,version:2}),(e:unknown)=>e instanceof Conflict&&e.code==='IDEMPOTENCY_MISMATCH');
 await assert.rejects(()=>approve(db,f.h,f.actor,loser,'new-key-'+loser,{...f.body,expected_facts_revision:'1'}),(e:unknown)=>e instanceof Conflict&&e.code==='INSUFFICIENT_POSITION');
 const rows=await db.query('SELECT instrument_code,quantity FROM app.holdings WHERE household_id=$1',[f.h]);assert.equal(rows.rows.find(r=>r.instrument_code==='PETR4').quantity,'3');assert.equal(rows.rows.length,1,'cash remains outside the invested-asset ledger');
 for(const [table,count] of [['events','1'],['event_legs','3'],['audit_log','1']])assert.equal((await db.query('SELECT count(*) FROM app.'+table+' WHERE household_id=$1',[f.h])).rows[0].count,count);
});
test('failed audit rolls back event, invested position, revision, proposal and idempotency result',async()=>{
 const f=await fixture();await db.query(`CREATE OR REPLACE FUNCTION app.test_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.household_id='${f.h}' THEN RAISE EXCEPTION 'fixture failure'; END IF; RETURN NEW; END $$; CREATE TRIGGER fixture_audit_failure BEFORE INSERT ON app.audit_log FOR EACH ROW EXECUTE FUNCTION app.test_fail_audit()`);
 try{await assert.rejects(()=>approve(db,f.h,f.actor,'p1','rollback01',f.body));assert.equal((await db.query('SELECT facts_revision FROM app.household_state WHERE household_id=$1',[f.h])).rows[0].facts_revision,'0');assert.equal((await db.query('SELECT count(*) FROM app.events WHERE household_id=$1',[f.h])).rows[0].count,'0');assert.equal((await db.query("SELECT quantity FROM app.holdings WHERE household_id=$1 AND instrument_code='PETR4'",[f.h])).rows[0].quantity,'10');assert.equal((await db.query('SELECT count(*) FROM app.command_results WHERE household_id=$1',[f.h])).rows[0].count,'0');assert.equal((await db.query("SELECT status FROM app.proposals WHERE household_id=$1 AND id='p1'",[f.h])).rows[0].status,'pending');}finally{await db.query('DROP TRIGGER fixture_audit_failure ON app.audit_log; DROP FUNCTION app.test_fail_audit()');}
});
