test('explicit account confirmation is scoped, audited, idempotent and changes only a new shadow version',async()=>{
 const dir=await mkdtemp(join(tmpdir(),'juanca-account-confirm-'));
 try{
  const h='account-confirm-'+randomUUID();const imports=[{id:'snapshot-import',user_id:h,owner:'Jorge',status:'processed',file_type:'positions',reference_date:'2026-08-01',created_at:'2026-08-02 00:00:00'},{id:'trade-import',user_id:h,owner:'Jorge',status:'processed',file_type:'chat_transaction',reference_date:'2026-10-05',created_at:'2026-10-06 00:00:00'}];
  const position={owner:'Jorge',account:'evidence-account',currency:'BRL',instrument_code:'SMAL11',quantity:'10',unit_price:'30',market_value_cents:'30000',reference_date:'2026-08-01'};
  const trade={owner:'Jorge',account:null,currency:'BRL',instrument_code:'SMAL11',quantity:'2',unit_price:'30',side:'sell',trade_date:'2026-10-05'};
  const tables={imports,import_records:[{id:1,import_id:'snapshot-import',record_kind:'position',payload:JSON.stringify(position)},{id:2,import_id:'trade-import',record_kind:'trade',payload:JSON.stringify(trade)}],market_quotes:[],fx_observations:[],portfolio_revisions:[{user_id:h,revision:0}],transaction_proposals:[],review_decisions:[],cost_basis:[],chat_messages:[],proposal_applications:[]};const content={format:1,tables,conversation_archive:[]};const canonical=JSON.stringify(content);const file=join(dir,'fixture.json');await writeFile(file,JSON.stringify({source_sha256:hash(canonical),exported_at:'2026-10-09T00:00:00.000Z',canonical_content:canonical,content}));
  const run=await importEnvelope(db,file);const original=await publish(db,run.run_id,h,'2026-10-09','2026-10-09T00:00:00.000Z');assert.equal(original.view.positions[0].quantity,'10');assert.ok(original.view.issues.some(i=>i.code==='unresolved_trade_account'));
  const command={run:run.run_id,household:h,trade_record_id:'2',snapshot_id:'snapshot-import:1'};
  await assert.rejects(()=>confirmSameAccount(db,{...command,snapshot_id:'wrong'}),(e:unknown)=>e instanceof Conflict&&e.code==='NOT_FOUND');
  assert.equal((await confirmSameAccount(db,command)).replayed,false);assert.equal((await confirmSameAccount(db,command)).replayed,true);
  const reconciled=await publish(db,run.run_id,h,'2026-10-09','2026-10-09T00:00:00.000Z');assert.equal(reconciled.view.positions[0].quantity,'8');assert.notEqual(reconciled.portfolio_version,original.portfolio_version);assert.equal((await portfolio(db,h,original.portfolio_version)).positions[0].quantity,'10');
  assert.equal((await db.query('SELECT count(*) FROM app.account_resolutions WHERE household_id=$1',[h])).rows[0].count,'1');
  assert.equal((await db.query('SELECT count(*) FROM app.audit_log WHERE household_id=$1 AND action=$2',[h,'account_resolution_confirmed'])).rows[0].count,'1');
  assert.equal((await db.query('SELECT facts_revision FROM app.household_state WHERE household_id=$1',[h])).rows[0].facts_revision,'1');
  assert.equal((await db.query('SELECT count(*) FROM app.events WHERE household_id=$1 AND application_status=$2',[h,'applied'])).rows[0].count,'0');
 }finally{await rm(dir,{recursive:true,force:true});}
});

test('manual pension snapshot is staged atomically and idempotently without publishing portfolio data',async()=>{
 const h='manual-pension-'+randomUUID(),actor='manual-pension-actor-'+randomUUID();
 await db.query('INSERT INTO app.households VALUES($1)',[h]);await db.query('INSERT INTO app.actors VALUES($1,$2)',[actor,'Manual pension fixture']);await db.query("INSERT INTO app.memberships VALUES($1,$2,'owner')",[h,actor]);await db.query("INSERT INTO app.owners VALUES($1,'jorge','Jorge')",[h]);
 const body={request_key:'telegram-pension-fixture-001',owner:'Jorge',institution:'Fixture Previdencia',reference_date:'2026-10-20',valuation_basis:'net',evidence_refs:['photo-fixture'],plans:[{plan_number:'Plano A',product_name:'PGBL',fund:'Fundo A',fund_cnpj:'12345678000199',gross_balance:'1200.50',net_balance:'1000.25',tax_regime:'regressivo'},{plan_number:'Plano B',product_name:'PGBL',fund:'Fundo A',fund_cnpj:'12345678000199',gross_balance:'2000',net_balance:'1800',tax_regime:'progressivo'}]};
 const first=await createManualExternalPositionSnapshot(db,h,actor,body),replay=await createManualExternalPositionSnapshot(db,h,actor,body);
 assert.equal(first.portfolio_published,false);assert.equal(first.plans,2);assert.equal(first.positions,2);assert.equal(replay.replayed,true);assert.equal(first.document_id,replay.document_id);
 const review=await listExternalPositionSnapshots(db,h),candidate=review.snapshots.find((item:{document_id:string;position_details?:{plans?:{plan_number:string}[]}[]})=>item.document_id===first.document_id);
 assert.equal(candidate?.invalid_rows,0);assert.equal(candidate?.rows,2);assert.equal(candidate?.latest,true);assert.equal(candidate?.published,false);
 assert.deepEqual(candidate?.position_details?.flatMap((detail:{plans?:{plan_number:string}[]})=>detail.plans?.map(plan=>plan.plan_number)??[]),['Plano A','Plano B']);
 const assertion=await db.query('SELECT quantity::text,raw_row FROM app.source_assertions WHERE household_id=$1 AND document_id=$2',[h,first.document_id]);assert.equal(assertion.rows[0].quantity,'1');assert.deepEqual(assertion.rows.map(row=>row.raw_row.market_value).sort(),['1000.25','1800']);assert.ok(assertion.rows.every(row=>row.raw_row.plans.length===1));
 assert.equal((await db.query('SELECT count(*) FROM app.external_position_snapshot_publications WHERE household_id=$1',[h])).rows[0].count,'0');
 await assert.rejects(()=>createManualExternalPositionSnapshot(db,h,actor,{...body,request_key:'telegram-pension-fixture-002',plans:[{...body.plans[0],fund_cnpj:'missing'}]}),(e:unknown)=>e instanceof Conflict&&e.code==='FUND_CNPJ_REQUIRED');
 await assert.rejects(()=>createManualExternalPositionSnapshot(db,h,actor,{...body,request_key:'telegram-pension-fixture-003',plans:[body.plans[0],{...body.plans[1],plan_number:body.plans[0].plan_number}]}),(e:unknown)=>e instanceof Conflict&&e.code==='DUPLICATE_PLAN_NUMBER');
 const photo=randomUUID();await db.query("INSERT INTO app.manual_photo_evidence(household_id,upload_id,owner_id,file_name,content_sha256) VALUES($1,$2,'jorge','pension.jpg',$3)",[h,photo,'a'.repeat(64)]);
 const withPhoto={...body,request_key:'pension-photo-fixture-001',evidence_refs:[{kind:'manual_photo',upload_id:photo}]};const staged=await createManualExternalPositionSnapshot(db,h,actor,withPhoto);assert.equal(staged.portfolio_published,false);assert.equal((await createManualExternalPositionSnapshot(db,h,actor,withPhoto)).replayed,true);
 assert.equal((await db.query('SELECT status FROM app.manual_photo_evidence WHERE household_id=$1 AND upload_id=$2',[h,photo])).rows[0].status,'linked');
 await assert.rejects(()=>createManualExternalPositionSnapshot(db,h,actor,{...withPhoto,request_key:'pension-photo-fixture-002'}),(e:unknown)=>e instanceof Conflict&&e.code==='PHOTO_EVIDENCE_UNAVAILABLE');
});

test('partial pension update splits a published legacy group and preserves the untouched plan date',async()=>{
 const dir=await mkdtemp(join(tmpdir(),'juanca-pension-carry-'));
 try{
  const h='pension-carry-'+randomUUID(),actor='pension-actor-'+randomUUID(),institution='Fixture Pension',cnpj='12345678000199',code=`PREV-${cnpj}`,legacyDoc='legacy-pension-'+randomUUID(),assertion='legacy-assertion-'+randomUUID();
  await db.query('INSERT INTO app.households VALUES($1)',[h]);await db.query('INSERT INTO app.actors VALUES($1,$2)',[actor,'Pension reviewer']);await db.query("INSERT INTO app.memberships VALUES($1,$2,'approver')",[h,actor]);
  const imports=[{id:'legacy-import',user_id:h,owner:'Jorge',status:'processed',file_type:'pension_statement',reference_date:'2026-10-24',created_at:'2026-10-24 12:00:00'}];
  const oldPlans=[{plan_number:'A',product_name:'PGBL',fund:'Fixture Fund',fund_cnpj:cnpj,gross_balance:'100',net_balance:'80',tax_regime:'Regressivo',market_value:'100',quantity:'1',unit_price:'100',currency:'BRL'},{plan_number:'B',product_name:'PGBL',fund:'Fixture Fund',fund_cnpj:cnpj,gross_balance:'50',net_balance:'40',tax_regime:'Regressivo',market_value:'50',quantity:'1',unit_price:'50',currency:'BRL'}];
  const legacyPayload={owner:'Jorge',institution,account:cnpj,asset_class:'private_pension',instrument_code:code,quantity:'1',unit_price:'150',market_value_minor:'15000',currency:'BRL',reference_date:'2026-10-24'};
  const tables={imports,import_records:[{id:1,import_id:'legacy-import',record_kind:'position',payload:JSON.stringify(legacyPayload)}],market_quotes:[],fx_observations:[],portfolio_revisions:[{user_id:h,revision:0}],transaction_proposals:[],review_decisions:[],cost_basis:[],chat_messages:[],proposal_applications:[]};
  const content={format:1,tables,conversation_archive:[]},canonical=JSON.stringify(content),file=join(dir,'fixture.json');await writeFile(file,JSON.stringify({source_sha256:hash(canonical),exported_at:'2026-10-24T12:00:00.000Z',canonical_content:canonical,content}));const imported=await importEnvelope(db,file);
  const owner=ownerId('Jorge'),provider='pension-provider-'+hash(institution.toLowerCase()).slice(0,24),custody='custody-'+hash([h,owner,provider,cnpj].join('|')).slice(0,32),legacyAccount=accountId(JSON.stringify(['Jorge','custody:'+custody]));
  await db.query("INSERT INTO app.custody_institutions(id,canonical_name,kind) VALUES($1,$2,'pension_provider') ON CONFLICT DO NOTHING",[provider,institution]);
  await db.query("INSERT INTO app.custody_accounts(household_id,id,owner_id,institution_id,external_reference,identity_basis) VALUES($1,$2,$3,$4,$5,'observed_reference')",[h,custody,owner,provider,cnpj]);
  await db.query("INSERT INTO app.accounts(household_id,id,owner_id,source_scope,identity_status) VALUES($1,$2,$3,$4,'known')",[h,legacyAccount,owner,JSON.stringify(['Jorge','custody:'+custody])]);
  await db.query("INSERT INTO app.source_documents(household_id,id,owner_id,source_system,report_kind,original_name,content_sha256,storage_key,effective_as_of,date_basis) VALUES($1,$2,$3,$4,'position','old.pdf',$5,'fixture','2026-10-24','user_reported')",[h,legacyDoc,owner,institution,'a'.repeat(64)]);
  await db.query("INSERT INTO app.source_assertions(household_id,id,document_id,owner_id,source_sheet,source_row,assertion_kind,instrument_code,asserted_on,quantity,raw_row,interpretation_status) VALUES($1,$2,$3,$4,'plans',2,'position',$5,'2026-10-24',1,$6,'observed')",[h,assertion,legacyDoc,owner,code,{institution,plans:oldPlans,valuation_basis:'gross',market_value:'150'}]);
  await db.query("INSERT INTO app.position_account_resolutions(run_id,household_id,source_record_id,resolution_version,snapshot_id,assertion_id,custody_account_id,decision,actor_id) VALUES($1,$2,'1',1,'legacy-import:1',$3,$4,'custody_account_reference_observed',$5)",[imported.run_id,h,assertion,custody,actor]);
  const baseline=await publish(db,imported.run_id,h,'2026-10-24','2026-10-25T00:00:00.000Z');
  await db.query("INSERT INTO app.holdings(household_id,account_id,instrument_code,currency,quantity,coverage_status,opening_as_of,opening_assertion_id) VALUES($1,$2,$3,'BRL',1,'verified','2026-10-24',$4)",[h,legacyAccount,code,assertion]);
  await db.query("INSERT INTO app.external_position_snapshot_publications(household_id,document_id,actor_id,request_key,request_hash,run_id,portfolio_version,position_count) VALUES($1,$2,$3,'fixture-legacy-publish',$4,$5,$6,1)",[h,legacyDoc,actor,hash('fixture-legacy'),imported.run_id,baseline.portfolio_version]);
  const input={request_key:'fixture-partial-update',owner:'Jorge',institution,reference_date:'2026-11-02',valuation_basis:'gross',update_scope:'plans',identity_unverified:true,plans:[{plan_number:'A',product_name:'PGBL',fund:'Fixture Fund',fund_cnpj:cnpj,gross_balance:'120',net_balance:'90',tax_regime:'Regressivo'}]};
  const draft=await createManualExternalPositionSnapshot(db,h,actor,input);let view=(await listExternalPositionSnapshots(db,h)).snapshots.find(s=>s.document_id===draft.document_id);assert.equal(view.invalid_rows,1);assert.equal(view.position_details.find((p:{plan_number:string})=>p.plan_number==='B').position_reference_date,'2026-10-24');
  const newPlan=view.position_details.find((p:{plan_number:string})=>p.plan_number==='A');await recordPensionIdentityDecision(db,h,actor,{request_key:'fixture-confirm-plan-A',assertion_id:newPlan.assertion_id,plan_number:'A',fund_name:'Fixture Fund',fund_cnpj:cnpj,source_locator:'fixture confirmation'});
  view=(await listExternalPositionSnapshots(db,h)).snapshots.find(s=>s.document_id===draft.document_id);const positions=view.legacy_positions.map(({account_id,instrument_code,currency,quantity,opening_as_of}:{account_id:string;instrument_code:string;currency:string;quantity:string;opening_as_of:string|null})=>({account_id,instrument_code,currency,quantity,opening_as_of})),identities=view.position_details.map((p:{assertion_id:string;identity_decision_id:string|null})=>({assertion_id:p.assertion_id,decision_id:p.identity_decision_id}));
  await publishExternalPositionSnapshot(db,h,actor,draft.document_id,{request_key:'fixture-publish-partial',content_sha256:draft.content_sha256,legacy_confirmation:{...view.legacy_basis,positions,identities}});
  const final=await portfolio(db,h),pension=final.positions.filter((p:{asset_class:string})=>p.asset_class==='private_pension');assert.equal(pension.length,2);assert.ok(pension.some((p:{reference_date:string;market_value_minor:string})=>p.reference_date==='2026-10-24'&&p.market_value_minor==='5000'));assert.ok(pension.some((p:{reference_date:string;market_value_minor:string})=>p.reference_date==='2026-11-02'&&p.market_value_minor==='12000'));
 }finally{await rm(dir,{recursive:true,force:true});}
});
